#!/bin/bash
# =============================================================================
# DEPLOY OVERNIGHT LOCAL CHANGES → GCP
# Generated by Claude overnight session 2026-05-22
# Run this once GCP SSH is back up.
#
# Usage:
#   chmod +x deploy_overnight_changes.sh
#   ./deploy_overnight_changes.sh
# =============================================================================

set -e

GCP="jackbeard@34.182.202.196"
KEY="$HOME/.ssh/gcp_apex"
REMOTE="~/institutional-tracker"
LOCAL="$(cd "$(dirname "$0")" && pwd)"

echo "=== APEX CAPITAL — Deploying overnight changes to GCP ==="
echo "Local: $LOCAL"
echo "Remote: $GCP:$REMOTE"
echo ""

# Test connection
echo "[1/8] Testing SSH connection..."
ssh -o ConnectTimeout=10 -i "$KEY" "$GCP" "echo 'SSH OK'" || {
    echo "ERROR: SSH failed. Is GCP running?"
    exit 1
}

# Push new files
echo "[2/8] Pushing cit_watchdog.py (new standalone watchdog)..."
scp -i "$KEY" "$LOCAL/cit_watchdog.py" "$GCP:$REMOTE/cit_watchdog.py"

echo "[3/8] Pushing predictive_model/ml_model_v4.py (new v4 model)..."
scp -i "$KEY" "$LOCAL/predictive_model/ml_model_v4.py" "$GCP:$REMOTE/predictive_model/ml_model_v4.py"

echo "[4/8] Pushing predictive_model/feature_engineer.py (sector_momentum_vs_spy)..."
scp -i "$KEY" "$LOCAL/predictive_model/feature_engineer.py" "$GCP:$REMOTE/predictive_model/feature_engineer.py"

echo "[5/8] Pushing predictive_model/historical_label_builder_fast.py (sector_momentum_vs_spy backfill)..."
scp -i "$KEY" "$LOCAL/predictive_model/historical_label_builder_fast.py" "$GCP:$REMOTE/predictive_model/historical_label_builder_fast.py"

echo "[6/8] Pushing overnight_ml_runner.py (v4 phase added)..."
scp -i "$KEY" "$LOCAL/overnight_ml_runner.py" "$GCP:$REMOTE/overnight_ml_runner.py"

echo "[7/8] Pushing predictive_model/predictor.py (version-aware dispatch)..."
scp -i "$KEY" "$LOCAL/predictive_model/predictor.py" "$GCP:$REMOTE/predictive_model/predictor.py"

echo "[8/8] Pushing requirements.txt (optuna + shap + xgboost added)..."
scp -i "$KEY" "$LOCAL/requirements.txt" "$GCP:$REMOTE/requirements.txt"

echo "[+1] Pushing ml_improvement_agent.py (v5-aware model loading)..."
scp -i "$KEY" "$LOCAL/ml_improvement_agent.py" "$GCP:$REMOTE/ml_improvement_agent.py"

echo "[+2] Pushing ml_drift_monitor.py (v5 bundle format support)..."
scp -i "$KEY" "$LOCAL/ml_drift_monitor.py" "$GCP:$REMOTE/ml_drift_monitor.py"

echo "[+3] Pushing predictive_model/backtest_predictive.py (version-aware predict)..."
scp -i "$KEY" "$LOCAL/predictive_model/backtest_predictive.py" "$GCP:$REMOTE/predictive_model/backtest_predictive.py"

echo "[+4] Pushing predictive_model/ml_model_v5.py (macro-conditioned stacking + SHAP pruning)..."
scp -i "$KEY" "$LOCAL/predictive_model/ml_model_v5.py" "$GCP:$REMOTE/predictive_model/ml_model_v5.py"

echo "[+5] Pushing ml_feature_drift_monitor.py (PSI input drift detection)..."
scp -i "$KEY" "$LOCAL/ml_feature_drift_monitor.py" "$GCP:$REMOTE/ml_feature_drift_monitor.py"

echo "[+6] Pushing institution_performance_tracker.py (per-institution attribution)..."
scp -i "$KEY" "$LOCAL/institution_performance_tracker.py" "$GCP:$REMOTE/institution_performance_tracker.py"

echo "[+7] Pushing dynamic_position_sizer.py (half-Kelly ML sizing)..."
scp -i "$KEY" "$LOCAL/dynamic_position_sizer.py" "$GCP:$REMOTE/dynamic_position_sizer.py"

echo "[+8] Pushing overnight_ml_runner.py (Phase 5: v5 training)..."
scp -i "$KEY" "$LOCAL/overnight_ml_runner.py" "$GCP:$REMOTE/overnight_ml_runner.py"

echo "[+9] Pushing predictive_model/predictor.py (v5 dispatch added)..."
scp -i "$KEY" "$LOCAL/predictive_model/predictor.py" "$GCP:$REMOTE/predictive_model/predictor.py"

echo ""
echo "=== All files pushed. Running post-deploy steps on GCP... ==="

# Install new dependencies
echo "[Post 1/4] Installing new dependencies (optuna, shap, xgboost)..."
ssh -i "$KEY" "$GCP" "cd $REMOTE && ~/venv/bin/pip install -q optuna>=3.5.0 shap>=0.44.0 xgboost>=1.7.0 && echo 'pip install OK'"

# Add cit_watchdog + feature drift monitor to crontab
echo "[Post 2/4] Adding cron entries (cit_watchdog every 3h, feature drift daily)..."
ssh -i "$KEY" "$GCP" "
    (crontab -l 2>/dev/null \
        | grep -v cit_watchdog \
        | grep -v ml_feature_drift_monitor \
        | grep -v institution_performance_tracker;
     echo '0 */3 * * * cd ~/institutional-tracker && ~/venv/bin/python3 cit_watchdog.py >> ~/institutional-tracker/logs/cit_watchdog_\$(date +\%Y\%m\%d).log 2>&1';
     echo '30 6 * * * cd ~/institutional-tracker && ~/venv/bin/python3 ml_feature_drift_monitor.py >> ~/institutional-tracker/logs/feature_drift_\$(date +\%Y\%m\%d).log 2>&1';
     echo '45 6 * * * cd ~/institutional-tracker && ~/venv/bin/python3 institution_performance_tracker.py >> ~/institutional-tracker/logs/inst_tracker_\$(date +\%Y\%m\%d).log 2>&1'
    ) | crontab -
    echo 'crontab updated'
"

# Run sector_momentum_vs_spy backfill
echo "[Post 3/4] Running sector_momentum_vs_spy backfill (uses existing price cache)..."
ssh -i "$KEY" "$GCP" "
    cd ~/institutional-tracker &&
    ~/venv/bin/python3 predictive_model/historical_label_builder_fast.py --backfill-sector-momentum 2>&1 | tail -5 &&
    echo 'Sector momentum backfill complete'
" || echo "WARNING: Sector momentum backfill failed (non-fatal — model falls back to 0.0)"

# Kick off overnight ML runner if after 9pm and not already running
echo "[Post 4/4] Checking if overnight ML runner should be started..."
ssh -i "$KEY" "$GCP" "
    HOUR=\$(date +%H)
    if [ \$HOUR -ge 21 ] || [ \$HOUR -le 6 ]; then
        if ! pgrep -f overnight_ml_runner > /dev/null; then
            echo 'Starting overnight ML runner...'
            nohup ~/venv/bin/python3 ~/institutional-tracker/overnight_ml_runner.py \
                > ~/institutional-tracker/logs/ml_runner_\$(date +%Y%m%d_%H%M).log 2>&1 &
            echo 'ML runner started (PID '\$!')'
        else
            echo 'ML runner already running — skipping'
        fi
    else
        echo 'Not overnight hours — skipping ML runner start'
    fi
"

echo ""
echo "=== Deploy complete ==="
echo ""
echo "Files deployed:"
echo "  + cit_watchdog.py                      (standalone watchdog, cron every 3h)"
echo "  + predictive_model/ml_model_v4.py          (Optuna LGB + SHAP + isotonic cal)"
echo "  + predictive_model/ml_model_v5.py          (macro-conditioned stacking + SHAP pruning)"
echo "  + predictive_model/feature_engineer.py      (+sector_momentum_vs_spy)"
echo "  + predictive_model/historical_label_builder_fast.py  (+sector backfill)"
echo "  + predictive_model/predictor.py            (v5 dispatch added)"
echo "  + overnight_ml_runner.py               (Phases 4+5: v4+v5 training)"
echo "  + requirements.txt                     (+optuna, +shap, +xgboost)"
echo "  + ml_feature_drift_monitor.py          (PSI input distribution drift, cron daily 06:30)"
echo "  + institution_performance_tracker.py   (per-institution win rate, cron daily 06:45)"
echo "  + dynamic_position_sizer.py            (half-Kelly ML-probability sizing)"
echo "  + ml_improvement_agent.py              (v5-aware model loading)"
echo "  + ml_drift_monitor.py                  (v5 bundle support)"
echo ""
echo "Next steps on GCP:"
echo "  - cit_watchdog cron:                 active (every 3h)"
echo "  - ml_feature_drift_monitor cron:     active (daily 06:30)"
echo "  - institution_performance_tracker:   active (daily 06:45)"
echo "  - sector_momentum_vs_spy:            backfilled on historical rows"
echo "  - overnight ML runner:               started if in overnight window"
echo "  - v4 + v5 training:                  will run on next overnight ML runner invocation"
